const Data = $('lead-submit').first().json.body;
const email = Data.email || "";
const phone = Data.phone || "";
const name = Data.name || "";

const emailValue = String(email ?? "").trim();
const phoneValue = String(phone ?? "").trim();
const nameValue = String(name ?? "").trim();


// =========================
// Email Validation
// =========================

const validEmail =
    /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)+$/
    .test(emailValue);


// =========================
// Phone Validation
// =========================

// Remove spaces, -, (, )
const cleanPhone = phoneValue.replace(/[\s\-().]/g, "");

// Allow:
// +201012345678
// 201012345678
// 01012345678
//
// Egyptian phone validation

const validPhone =
    /^(?:\+20|20|0)1[0125][0-9]{8}$/.test(cleanPhone);


// =========================
// Name Validation
// =========================

const validName =
    /^[A-Za-z\u0600-\u06FF]+(?:[\s'-][A-Za-z\u0600-\u06FF]+)*$/
    .test(nameValue);


// =========================
// Final Validation
// =========================

const isValid =
    validEmail &&
    validPhone &&
    validName;


return {
  ...Data,
  isValid
};

