<script>

    // ==========================================
    // Elements
    // ==========================================

    const form = document.getElementById("leadForm");
    const submitBtn = document.getElementById("submitBtn");

    const nameInput = document.getElementById("name");
    const emailInput = document.getElementById("email");
    const phoneInput = document.getElementById("phone");

    const nameError = document.getElementById("nameError");
    const emailError = document.getElementById("emailError");
    const phoneError = document.getElementById("phoneError");


    // ==========================================
    // Name Validation
    // ==========================================

    function validateName() {

        const name = nameInput.value.trim();

        // Required
        if (!name) {

            nameError.textContent =
                "Name is required.";

            nameInput.classList.add("invalid");
            nameInput.classList.remove("valid");

            return false;
        }


        // Letters only
        // Supports English + Arabic
        // Allows spaces, apostrophe and hyphen
        const nameRegex =
            /^[A-Za-z\u0600-\u06FF]+(?:[\s'-][A-Za-z\u0600-\u06FF]+)*$/;


        if (!nameRegex.test(name)) {

            nameError.textContent =
                "Please enter a valid name.";

            nameInput.classList.add("invalid");
            nameInput.classList.remove("valid");

            return false;
        }


        // Minimum length
        if (name.length < 2) {

            nameError.textContent =
                "Name must be at least 2 characters.";

            nameInput.classList.add("invalid");
            nameInput.classList.remove("valid");

            return false;
        }


        // Valid
        nameError.textContent = "";

        nameInput.classList.remove("invalid");
        nameInput.classList.add("valid");

        return true;
    }


    // ==========================================
    // Email Validation
    // ==========================================

    function validateEmail() {

        const email = emailInput.value.trim();


        const emailRegex =
            /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)+$/;


        // Required
        if (!email) {

            emailError.textContent =
                "Email is required.";

            emailInput.classList.add("invalid");
            emailInput.classList.remove("valid");

            return false;
        }


        // Format
        if (!emailRegex.test(email)) {

            emailError.textContent =
                "Please enter a valid email address.";

            emailInput.classList.add("invalid");
            emailInput.classList.remove("valid");

            return false;
        }


        // Valid
        emailError.textContent = "";

        emailInput.classList.remove("invalid");
        emailInput.classList.add("valid");

        return true;
    }


    // ==========================================
    // Egyptian Phone Validation
    // ==========================================

    function validatePhone() {

        const phone = phoneInput.value.trim();


        // Remove spaces, -, (, ), .
        const cleanPhone =
            phone.replace(/[\s\-().]/g, "");


        // Egyptian mobile numbers
        //
        // 01012345678
        // 01112345678
        // 01212345678
        // 01512345678
        //
        // Also accepts:
        // +201012345678
        // 201012345678

        const phoneRegex =
            /^(?:\+20|20|0)1[0125][0-9]{8}$/;


        // Required
        if (!phone) {

            phoneError.textContent =
                "Phone number is required.";

            phoneInput.classList.add("invalid");
            phoneInput.classList.remove("valid");

            return false;
        }


        // Format
        if (!phoneRegex.test(cleanPhone)) {

            phoneError.textContent =
                "Enter a valid Egyptian phone number.";

            phoneInput.classList.add("invalid");
            phoneInput.classList.remove("valid");

            return false;
        }


        // Valid
        phoneError.textContent = "";

        phoneInput.classList.remove("invalid");
        phoneInput.classList.add("valid");

        return true;
    }


    // ==========================================
    // Live Validation
    // ==========================================

    nameInput.addEventListener(
        "input",
        validateName
    );

    emailInput.addEventListener(
        "input",
        validateEmail
    );

    phoneInput.addEventListener(
        "input",
        validatePhone
    );


    // ==========================================
    // Form Submit
    // ==========================================

    form.addEventListener(
        "submit",
        async function (event) {

            event.preventDefault();


            // ==========================================
            // Validate before sending
            // ==========================================

            const validName =
                validateName();

            const validEmail =
                validateEmail();

            const validPhone =
                validatePhone();


            // Stop if validation fails
            if (
                !validName ||
                !validEmail ||
                !validPhone
            ) {

                return;
            }


            // ==========================================
            // Disable button
            // ==========================================

            submitBtn.disabled = true;

            submitBtn.textContent =
                "Submitting...";


            // ==========================================
            // Get form data
            // ==========================================

            const formData =
                new FormData(form);


            const data =
                Object.fromEntries(
                    formData.entries()
                );


            try {

                // ==========================================
                // Send to n8n
                // ==========================================

                const response =
                    await fetch(
                        "https://cloudfare.ziad-n8n.cfd/webhook/lead-submit",
                        {
                            method: "POST",

                            headers: {
                                "Content-Type":
                                    "application/json"
                            },

                            body:
                                JSON.stringify(data)
                        }
                    );


                // ==========================================
                // HTTP Error
                // ==========================================

                if (!response.ok) {

                    const errorText =
                        await response.text();

                    console.error(
                        "n8n Error:",
                        response.status,
                        errorText
                    );

                    throw new Error(
                        "Server returned " +
                        response.status
                    );
                }


                // ==========================================
                // Get n8n response
                // ==========================================

                const result =
                    await response.json();


                // ==========================================
                // CASE 1
                // Duplicate Lead
                // ==========================================

                if (
                    result.alreadyExists === true
                ) {

                    const reason =
                        result.phoneExists &&
                        result.emailExists

                            ? "both"

                            : result.emailExists

                            ? "email"

                            : result.phoneExists

                            ? "phone"

                            : "unknown";


                    window.location.href =
                        "https://cloudfare.ziad-n8n.cfd/webhook/duplicate?reason=" +
                        encodeURIComponent(reason);

                    return;
                }


                // ==========================================
                // CASE 2
                // New Lead
                // ==========================================

                if (
                    result.success === true &&
                    result.leadId
                ) {

                    const leadId =
                        result.leadId;


                    window.location.href =
                        "https://cloudfare.ziad-n8n.cfd/webhook/thanks?leadId=" +
                        encodeURIComponent(leadId);

                    return;
                }


                // ==========================================
                // CASE 3
                // Unexpected response
                // ==========================================

                console.error(
                    "Unexpected response from n8n:",
                    result
                );

                throw new Error(
                    "Invalid response from server"
                );


            } catch (error) {

                console.error(
                    "Submission Error:",
                    error
                );


                alert(
                    "Something went wrong. Please check your information and try again."
                );


                // Enable button again
                submitBtn.disabled = false;

                submitBtn.textContent =
                    "Submit Inquiry";

            }

        }
    );

</script>

</body>
</html>

