let emailExists = false;

for (const item of sheetRows) {

    const row = item.json;
    const sheetPhone = String(row.Phone || '').trim();
    const sheetEmail = String(row.Email || '').trim().toLowerCase();

    if (formPhone == sheetPhone ) {
        phoneExists = true;
    }

    if (formEmail == sheetEmail) {
        emailExists = true;
    }
}

return [{
    json: {
        ...data,
        phoneExists,
        emailExists,
        alreadyExists: phoneExists || emailExists
    }
}];

